I am using pytest and FastAPI's TestClient.
I have set up some cookies in the TestClient's session, I want these cookies to be available during my request call. Also the cookiejar needs to be updated during my subsequest request calls.

```
import pytest
from requests.cookies import create_cookie
from fastapi.testclient import TestClient

@pytest.fixture(scope='session')
def cookie_token():
    required_args = {
        'name': 'token',
        'value': 'value'
    }
    optional_args = {
    'domain':'example.com',
    'path':'/',
    'secure':True,
    'expires':None,
    'rest':{'HttpOnly': True}    
    }
    return create_cookie(**required_args, **optional_args)

@pytest.fixture(scope='session')
def client(cookie_token):
    with TestClient(app) as client:
        client.cookies.set_cookie(cookie_token)
        yield client

def test_authenticate(client):
    headers = {}
    headers.update({'Content-Type': 'application/json'})
    response = client.get('/api/auth/authenticate', headers=headers)
    assert response.status_code == 200


def test_verify(client):
    headers = {}
    headers.update({'Content-Type': 'application/json'})
    response = client.get('/api/auth/verify', headers=headers)
    assert response.status_code == 200


